SELECT ROUND(CAST((
    (SELECT AVG(CASE WHEN funcimp = 'Severe' THEN 3 WHEN funcimp = 'Moderate' THEN 2 WHEN funcimp = 'Mild' THEN 1 ELSE 0 END) FROM assessmentsocialanddiagnosis) -
    (SELECT AVG(CASE WHEN support_and_resources->>'community_resources' = 'Comprehensive' THEN 3 WHEN support_and_resources->>'community_resources' = 'Adequate' THEN 2 WHEN support_and_resources->>'community_resources' = 'Limited' THEN 1 ELSE 0 END) FROM facilities)
) AS numeric), 2);

SELECT COUNT(*) FROM facilities 
WHERE (CASE WHEN envstress = 'Severe' THEN 3 WHEN envstress = 'Moderate' THEN 2 WHEN envstress = 'Mild' THEN 1 END) - 
    (CASE WHEN support_and_resources->>'community_resources' = 'Comprehensive' THEN 3 WHEN support_and_resources->>'community_resources' = 'Adequate' THEN 2 WHEN support_and_resources->>'community_resources' = 'Limited' THEN 1 END) > 1.0;

